package provider

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
)

// TestRateLimitRetry runs data "lumos_current_user" against a fake API that
// answers 429 with a Retry-After, and checks the provider waits it out and
// retries, or fails at once with a rate-limit error when Retry-After is
// longer than it retries for.
//
// The retry loop is generated by Speakeasy from the overlay's root
// x-speakeasy-retries, so this is what catches a generator upgrade or overlay
// change that stops retrying 429s or ignores Retry-After. It uses a fake API
// because apiserver's rate limit can't be tripped on demand.
func TestRateLimitRetry(t *testing.T) {
	cases := []struct {
		name       string
		retryAfter string
		// limitEvery is how many requests in a row get a 429 before one
		// succeeds; 0 means every request gets a 429.
		limitEvery int
		wantErr    string
		// wantPerRead is how many requests one read sends.
		wantPerRead int
		minWait     time.Duration
		maxWait     time.Duration
	}{
		{
			name:        "429 then success waits out Retry-After",
			retryAfter:  "1",
			limitEvery:  1,
			wantPerRead: 2,
			minWait:     time.Second,
		},
		{
			name:        "Retry-After past the retry budget fails at once",
			retryAfter:  "300",
			wantErr:     "v1GetCurrentUser: the Lumos API is still rate limiting this request (status 429, Retry-After: 300)",
			wantPerRead: 1,
			maxWait:     30 * time.Second,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var mu sync.Mutex
			var requests int
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path != "/v1/users/current" {
					http.NotFound(w, r)
					return
				}
				mu.Lock()
				requests++
				limited := tc.limitEvery == 0 || (requests-1)%(tc.limitEvery+1) < tc.limitEvery
				mu.Unlock()
				w.Header().Set("Content-Type", "application/json")
				if limited {
					w.Header().Set("Retry-After", tc.retryAfter)
					w.WriteHeader(http.StatusTooManyRequests)
					fmt.Fprint(w, `{"error":{"message":"Too many requests","code":"rate_limited"}}`)
					return
				}
				fmt.Fprint(w, `{"id":"u1","email":"u1@example.com"}`)
			}))
			defer server.Close()

			step := resource.TestStep{
				Config: fmt.Sprintf(`
provider "lumos" {
  server_url  = %q
  http_bearer = "test-token"
}

data "lumos_current_user" "me" {}
`, server.URL),
				Check: resource.TestCheckResourceAttr("data.lumos_current_user.me", "id", "u1"),
			}
			if tc.wantErr != "" {
				step.Check = nil
				// Terraform wraps long diagnostics, so any space may be a newline.
				step.ExpectError = regexp.MustCompile(strings.ReplaceAll(regexp.QuoteMeta(tc.wantErr), " ", `\s+`))
			}
			start := time.Now()
			resource.UnitTest(t, resource.TestCase{
				ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
				Steps:                    []resource.TestStep{step},
			})
			elapsed := time.Since(start)

			// Terraform reads the data source more than once per test step, so
			// the server sees the same requests once per read.
			mu.Lock()
			defer mu.Unlock()
			if requests == 0 || requests%tc.wantPerRead != 0 {
				t.Fatalf("server got %d requests, want whole reads of %d", requests, tc.wantPerRead)
			}
			if tc.minWait > 0 && elapsed < tc.minWait {
				t.Fatalf("took %s, want at least the %s Retry-After", elapsed, tc.minWait)
			}
			if tc.maxWait > 0 && elapsed > tc.maxWait {
				t.Fatalf("took %s, want under %s: a Retry-After past the budget should fail without waiting", elapsed, tc.maxWait)
			}
		})
	}
}
